import React, { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Sparkles, MapPin, Crown, ArrowRight } from "lucide-react";
import { BRAND } from "../types";

// ══════════════════════════════════════════════════════════════
// Your wedding scene image — swap this URL for your own
// ══════════════════════════════════════════════════════════════
const BACKGROUND_IMAGE = "/images/pita_Wide-angle_3D_rendered_luxury_wedding_venue_showcase_birds_eye_f75ac395-fb47-45cb-9862-8b54a5c34201.jpg";

// Zoom scale — how close the camera zooms in
const ZOOM = 1.6;

// Duration of the cinematic zoom transition (seconds)
const ZOOM_DURATION = 0.85;

// ── Products ────────────────────────────────────────────────
// position  = where the hotspot dot sits on screen (CSS %)
// focusPoint = which part of the image to zoom into (0–100 %)
// Tuned to the provided wedding venue photograph
const products = [
  {
    id: 1,
    name: "Ceiling Drapes",
    subtitle: "Flowing gold & ivory overhead drapes",
    position: { top: "12%", left: "35%" },
    focusPoint: { x: 35, y: 10 },
  },
  {
    id: 2,
    name: "Chandeliers",
    subtitle: "Crystal chandeliers with warm glow",
    position: { top: "22%", left: "58%" },
    focusPoint: { x: 58, y: 22 },
  },
  {
    id: 3,
    name: "Chair Covers",
    subtitle: "White covers with gold sash bows",
    position: { top: "72%", left: "22%" },
    focusPoint: { x: 22, y: 72 },
  },
  {
    id: 4,
    name: "Table Covers",
    subtitle: "Gold-clothed round tables",
    position: { top: "58%", left: "38%" },
    focusPoint: { x: 38, y: 58 },
  },
  {
    id: 5,
    name: "Artificial Flowers",
    subtitle: "Luxurious floral arrangements",
    position: { top: "52%", left: "12%" },
    focusPoint: { x: 12, y: 52 },
  },
  {
    id: 6,
    name: "Decor Accessories",
    subtitle: "Candelabras, vases & gold accents",
    position: { top: "48%", left: "35%" },
    focusPoint: { x: 35, y: 48 },
  },
  {
    id: 7,
    name: "Curtains",
    subtitle: "Sheer floor-to-ceiling installations",
    position: { top: "38%", left: "88%" },
    focusPoint: { x: 88, y: 38 },
  },
  {
    id: 8,
    name: "Premium Fabrics",
    subtitle: "Luxurious flowing silk textures",
    position: { top: "14%", left: "75%" },
    focusPoint: { x: 75, y: 14 },
  },
];

// ── Helpers ─────────────────────────────────────────────────
/** Calculate CSS transform to center a focus point in the viewport */
function getTransform(fp: { x: number; y: number }) {
  const tx = (50 - fp.x) * (ZOOM / (ZOOM - 1));
  const ty = (50 - fp.y) * (ZOOM / (ZOOM - 1));
  return `scale(${ZOOM}) translate(${tx}%, ${ty}%)`;
}

// ══════════════════════════════════════════════════════════════
// Component
// ══════════════════════════════════════════════════════════════
export default function Hero3D({ onOpenQuote }: { onOpenQuote: () => void }) {
  const [activeId, setActiveId] = useState<number | null>(null);
  const [imgLoaded, setImgLoaded] = useState(false);

  const scrollToCollections = () =>
    document.getElementById("collections")?.scrollIntoView({ behavior: "smooth" });

  const activeProduct = activeId !== null ? products.find((p) => p.id === activeId) : null;
  const isZoomed = activeId !== null;

  const handleEnter = useCallback((id: number) => setActiveId(id), []);
  const handleLeave = useCallback(() => setActiveId(null), []);

  // CSS transform for the background — driven by inline style, animated via CSS transition
  const bgTransform =
    isZoomed && activeProduct
      ? getTransform(activeProduct.focusPoint)
      : "scale(1) translate(0%, 0%)";

  const bgOrigin =
    isZoomed && activeProduct
      ? `${activeProduct.focusPoint.x}% ${activeProduct.focusPoint.y}%`
      : "50% 50%";

  return (
    <section id="top" className="relative min-h-screen overflow-hidden select-none">
      {/* ── Loading skeleton ── */}
      {!imgLoaded && (
        <div className="absolute inset-0 bg-gradient-to-br from-amber-900 via-amber-800 to-gray-900 flex items-center justify-center z-50">
          <div className="text-center">
            <div className="w-14 h-14 border-4 border-amber-400 border-t-transparent rounded-full animate-spin mx-auto mb-3" />
            <p className="text-amber-400/80 text-sm tracking-wide">Loading experience…</p>
          </div>
        </div>
      )}

      {/* ── Background image (cinematic zoom via CSS transition) ── */}
      <div
        className="absolute inset-[-10%] w-[120%] h-[120%]"
        style={{
          backgroundImage: `url('${BACKGROUND_IMAGE}')`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transform: bgTransform,
          transformOrigin: bgOrigin,
          transition: `transform ${ZOOM_DURATION}s cubic-bezier(0.25, 0.46, 0.45, 0.94)`,
          willChange: "transform",
        }}
        onLoad={() => setImgLoaded(true)}
      />
      {/* Hidden img to detect load */}
      <img
        src={BACKGROUND_IMAGE}
        alt=""
        className="hidden"
        onLoad={() => setImgLoaded(true)}
      />

      {/* ── Dark overlay (lightens during zoom) ── */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "linear-gradient(to bottom, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.35) 40%, rgba(0,0,0,0.75) 100%)",
          opacity: isZoomed ? 0.25 : 0.55,
          transition: "opacity 0.6s ease",
        }}
      />

      {/* ── Vignette (intensifies during zoom) ── */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.7) 100%)",
          opacity: isZoomed ? 0.9 : 0.5,
          transition: "opacity 0.6s ease",
        }}
      />

      {/* ── Radial focus glow that follows the zoom centre ── */}
      <div
        className="absolute inset-0 pointer-events-none z-10"
        style={{
          background: isZoomed && activeProduct
            ? `radial-gradient(circle 35% at ${activeProduct.focusPoint.x}% ${activeProduct.focusPoint.y}%, rgba(212,175,55,0.15), transparent 70%)`
            : "none",
          opacity: isZoomed ? 1 : 0,
          transition: "opacity 0.5s ease",
        }}
      />

      {/* ── Hotspot layer ── */}
      <div className="absolute inset-0 z-20">
        {products.map((product) => {
          const isActive = activeId === product.id;
          return (
            <motion.div
              key={product.id}
              className="absolute"
              style={{
                top: product.position.top,
                left: product.position.left,
                transform: "translate(-50%, -50%)",
              }}
              onMouseEnter={() => handleEnter(product.id)}
              onMouseLeave={handleLeave}
              initial={{ scale: 0, opacity: 0 }}
              animate={{ scale: 1, opacity: isZoomed && !isActive ? 0.15 : 1 }}
              transition={{
                delay: 0.4 + product.id * 0.08,
                type: "spring",
                stiffness: 260,
                damping: 20,
              }}
            >
              {/* ── Pulsing dot ── */}
              <motion.div className="relative w-10 h-10 md:w-12 md:h-12 cursor-pointer" whileHover={{ scale: 1.35 }}>
                {/* Outer ring */}
                <motion.div
                  className="absolute inset-0 border-2 border-amber-400 rounded-full"
                  animate={
                    isActive
                      ? { scale: [1, 2.2, 1], opacity: [1, 0, 1] }
                      : { scale: [1, 1.6, 1], opacity: [0.5, 0, 0.5] }
                  }
                  transition={{ duration: 2, repeat: Infinity }}
                />
                {/* Inner dot */}
                <motion.div
                  className="absolute inset-1.5 rounded-full flex items-center justify-center"
                  style={{
                    background: "linear-gradient(135deg, #d4af37, #c9a032)",
                    boxShadow: isActive
                      ? "0 0 30px rgba(212,175,55,0.7)"
                      : "0 0 15px rgba(212,175,55,0.35)",
                  }}
                  animate={{ scale: isActive ? [1, 1.2, 1] : [1, 1.08, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                >
                  <div className="w-2 h-2 bg-white rounded-full" />
                </motion.div>
              </motion.div>

              {/* ── Label card ── */}
              <AnimatePresence>
                {isActive && (
                  <motion.div
                    initial={{ opacity: 0, x: -12, scale: 0.92 }}
                    animate={{ opacity: 1, x: 0, scale: 1 }}
                    exit={{ opacity: 0, x: -12, scale: 0.92 }}
                    transition={{ duration: 0.3, ease: "easeOut" }}
                    className="absolute left-full ml-5 top-1/2 -translate-y-1/2 whitespace-nowrap z-50"
                  >
                    {/* connector line */}
                    <div className="absolute right-full top-1/2 -translate-y-1/2 w-5 h-[2px] bg-gradient-to-r from-transparent to-amber-400" />

                    <div className="relative bg-gradient-to-br from-white/95 via-amber-50/90 to-white/95 backdrop-blur-xl rounded-2xl px-6 py-4 shadow-2xl shadow-black/40 border border-amber-300/40">
                      {/* gold accent bar */}
                      <div className="absolute -left-1 top-3 bottom-3 w-1 rounded-full bg-gradient-to-b from-amber-400 via-amber-500 to-amber-400" />

                      <h3 className="text-amber-700 font-bold text-base md:text-lg mb-0.5 leading-tight">
                        {product.name}
                      </h3>
                      <p className="text-gray-500 text-xs md:text-sm mb-2">
                        {product.subtitle}
                      </p>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          scrollToCollections();
                        }}
                        className="text-xs text-amber-600 hover:text-amber-800 flex items-center gap-1.5 font-medium transition-all hover:gap-2.5"
                      >
                        View Collection
                        <ArrowRight size={12} />
                      </button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>

      {/* ── Floating golden particles ── */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none z-10">
        {[...Array(18)].map((_, i) => (
          <motion.div
            key={i}
            className="absolute w-1 bg-amber-300/50 rounded-full"
            style={{
              left: `${5 + (i * 5.3) % 90}%`,
              top: `${8 + (i * 7.1) % 85}%`,
            }}
            animate={{
              y: [0, -70, 0],
              x: [0, Math.sin(i * 0.6) * 20, 0],
              opacity: [0, 0.7, 0],
              scale: [0, 1.2, 0],
            }}
            transition={{
              duration: 4 + (i % 4),
              repeat: Infinity,
              delay: i * 0.3,
              ease: "easeInOut",
            }}
          />
        ))}
      </div>

      {/* ── Content overlay (fades out during zoom) ── */}
      <AnimatePresence>
        {!isZoomed && (
          <motion.div
            key="hero-content"
            className="relative z-30 container mx-auto px-6 text-center pointer-events-none"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0, scale: 0.97 }}
            transition={{ duration: 0.5 }}
          >
            <div className="max-w-5xl mx-auto">
              {/* Location badge */}
              <motion.div
                initial={{ opacity: 0, y: -30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.4 }}
                className="flex items-center justify-center gap-4 mb-8"
              >
                <div className="h-px w-16 md:w-24 bg-gradient-to-r from-transparent to-amber-400" />
                <div className="flex items-center gap-2 text-xs md:text-sm font-semibold text-amber-400 tracking-[0.25em] uppercase">
                  <motion.div animate={{ scale: [1, 1.2, 1] }} transition={{ duration: 2, repeat: Infinity }}>
                    <MapPin size={14} />
                  </motion.div>
                  <span className="hidden sm:inline">Ludhiana, Punjab</span>
                  <span className="hidden md:inline">|</span>
                  <span>Pan India Delivery</span>
                </div>
                <div className="h-px w-16 md:w-24 bg-gradient-to-l from-transparent to-amber-400" />
              </motion.div>

              {/* Title */}
              <motion.h1
                initial={{ opacity: 0, y: 50 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.6, duration: 0.8 }}
                className="text-5xl sm:text-6xl md:text-7xl lg:text-[90px] font-bold text-white mb-4 tracking-tight"
                style={{ fontFamily: "Georgia, serif" }}
              >
                {["D", "SAJAWAT"].map((word, wi) => (
                  <span key={wi} className="inline-block mr-3 md:mr-6">
                    {word.split("").map((letter, li) => (
                      <motion.span
                        key={`${wi}-${li}`}
                        className="inline-block"
                        initial={{ opacity: 0, y: 80, rotateX: -90 }}
                        animate={{ opacity: 1, y: 0, rotateX: 0 }}
                        transition={{
                          duration: 0.7,
                          delay: 0.7 + wi * 0.4 + li * 0.06,
                          ease: [0.34, 1.56, 0.64, 1],
                        }}
                      >
                        <span className="bg-gradient-to-r from-amber-200 via-amber-400 to-amber-200 bg-clip-text text-transparent">
                          {letter}
                        </span>
                      </motion.span>
                    ))}
                  </span>
                ))}
              </motion.h1>

              {/* Tagline */}
              <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 1.1, duration: 0.6 }}
                className="flex items-center justify-center gap-3 md:gap-5 mb-6"
              >
                <motion.div
                  animate={{ rotate: [0, 15, -15, 0], scale: [1, 1.15, 1] }}
                  transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
                >
                  <Crown className="text-amber-400" size={28} />
                </motion.div>
                <p
                  className="text-xl md:text-3xl lg:text-4xl text-amber-400 italic"
                  style={{ fontFamily: "Georgia, serif" }}
                >
                  {BRAND.tagline}
                </p>
                <motion.div
                  animate={{ rotate: [0, -15, 15, 0], scale: [1, 1.15, 1] }}
                  transition={{ duration: 3, repeat: Infinity, ease: "easeInOut", delay: 0.5 }}
                >
                  <Crown className="text-amber-400" size={28} />
                </motion.div>
              </motion.div>

              {/* Subtitle */}
              <motion.p
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.3 }}
                className="text-base md:text-lg lg:text-xl text-white/80 max-w-2xl mx-auto mb-10 leading-relaxed"
              >
                Hover over the glowing dots to explore our complete wedding decor collection.
              </motion.p>

              {/* CTAs */}
              <motion.div
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.5 }}
                className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center items-center pointer-events-auto"
              >
                <motion.button
                  onClick={scrollToCollections}
                  className="px-8 md:px-12 py-4 md:py-5 bg-gradient-to-r from-amber-400 via-amber-500 to-amber-400 bg-[length:200%_100%] text-white font-bold rounded-full flex items-center justify-center gap-3 text-base md:text-lg shadow-2xl shadow-amber-500/40 relative overflow-hidden"
                  whileHover={{ scale: 1.05, boxShadow: "0 25px 80px rgba(212,175,55,0.5)" }}
                  whileTap={{ scale: 0.98 }}
                >
                  <motion.div
                    className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -skew-x-12"
                    initial={{ x: "-100%" }}
                    whileHover={{ x: "200%" }}
                    transition={{ duration: 0.7 }}
                  />
                  <Sparkles size={20} className="relative z-10" />
                  <span className="relative z-10">Explore Collections</span>
                </motion.button>

                <motion.button
                  onClick={onOpenQuote}
                  className="px-8 md:px-12 py-4 md:py-5 bg-white/10 backdrop-blur-xl border-2 border-white/40 text-white font-bold rounded-full flex items-center justify-center gap-3 text-base md:text-lg hover:bg-white hover:text-gray-900 transition-all"
                  whileHover={{ scale: 1.05, borderColor: "rgba(212,175,55,0.8)", boxShadow: "0 20px 60px rgba(212,175,55,0.2)" }}
                  whileTap={{ scale: 0.98 }}
                >
                  Get a Quote
                  <motion.span animate={{ x: [0, 6, 0] }} transition={{ duration: 1.5, repeat: Infinity }} className="text-xl">
                    →
                  </motion.span>
                </motion.button>
              </motion.div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Instruction tooltip ── */}
      <AnimatePresence>
        {!isZoomed && (
          <motion.div
            key="tooltip"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 10 }}
            transition={{ delay: 2.2, duration: 0.5 }}
            className="absolute bottom-28 left-1/2 -translate-x-1/2 z-30"
          >
            <motion.div
              className="bg-white/10 backdrop-blur-md rounded-full px-5 py-2.5 border border-white/20"
              animate={{ y: [0, 6, 0] }}
              transition={{ duration: 2.5, repeat: Infinity }}
            >
              <p className="text-white/90 text-sm flex items-center gap-2">
                <motion.span
                  className="w-2.5 h-2.5 bg-amber-400 rounded-full inline-block"
                  animate={{ scale: [1, 1.5, 1], opacity: [1, 0.5, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
                Hover the glowing dots to explore products
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Bottom gradient fade ── */}
      <div className="absolute bottom-0 left-0 right-0 h-32 md:h-40 bg-gradient-to-t from-[#fdf6eb] to-transparent pointer-events-none z-40" />
    </section>
  );
}
